{
const $=s=>document.querySelector(s);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const inr=n=>'₹'+Math.round(n||0).toLocaleString('en-IN');
const pad=n=>String(n).padStart(2,'0');const ymd=d=>d.getFullYear()+'-'+pad(d.getMonth()+1)+'-'+pad(d.getDate());
const NOW=new Date(),todayS=ymd(NOW),curMK=todayS.slice(0,7);
const addDays=(ds,n)=>{const d=new Date(ds+'T00:00:00');d.setDate(d.getDate()+n);return ymd(d)};
const mkShift=(mk,n)=>{const[y,m]=mk.split('-').map(Number);return ymd(new Date(y,m-1+n,1)).slice(0,7)};
const fdate=ds=>ds?new Date(ds.slice(0,10)+'T00:00:00').toLocaleDateString('en-IN',{day:'2-digit',month:'short',year:'numeric'}):'—';
const fdt=iso=>iso?new Date(iso).toLocaleString('en-IN',{day:'2-digit',month:'short',hour:'2-digit',minute:'2-digit'}):'—';
const mname=mk=>{const[y,m]=mk.split('-').map(Number);return new Date(y,m-1,1).toLocaleString('en-IN',{month:'short',year:'numeric'})};
const uid=p=>p+Date.now().toString(36).slice(-4)+Math.random().toString(36).slice(2,5);
const chip=(t,c)=>`<span class="chip ${c||''}">${esc(t)}</span>`;
const toast=m=>{const t=$('#toast');t.textContent=m;t.classList.add('on');clearTimeout(toast.h);toast.h=setTimeout(()=>t.classList.remove('on'),2600)};
const fv=(r,n)=>{const el=r.querySelector(`[name="${n}"]`);return el?(el.type==='checkbox'?el.checked:el.value.trim()):''};
const ADMIN_URL='https://claude.ai/artifact/6xMdcPgxup15R4LvdqMA7W';

const SVC=[['recruitment','Recruitment & Sourcing'],['onboarding','Onboarding & Documentation'],['bgv','Background Verification'],['attendance','Attendance, Shifts & Rosters'],['leave','Leave & Holidays'],['payroll','Payroll & Salary Payouts'],['compliance','PF, ESI & Labour Law Compliance'],['performance','Performance & Incentives'],['relations','Employee Relations & Helpdesk'],['exit','Exit & Full and Final']];
const svcName=id=>(SVC.find(s=>s[0]===id)||[0,id])[1];
const STAGES=['New','Contacted','Demo scheduled','Proposal sent','Won','Lost'];
const STC={New:'c-info',Contacted:'c-b','Demo scheduled':'c-warn','Proposal sent':'c-warn',Won:'c-ok',Lost:'c-bad'};
const TSTC={Onboarding:'c-warn',Active:'c-ok',Suspended:'c-bad',Churned:''};

/* ================= STATE ================= */
const KEY='salonhr-console-v1';let S=null;try{S=JSON.parse(localStorage.getItem(KEY)||'null')}catch(e){}
const save=()=>{try{localStorage.setItem(KEY,JSON.stringify(S))}catch(e){}};
function seed(){
  const plans=[{id:'starter',name:'Starter',price:1499,upto:10,services:['attendance','leave','payroll']},{id:'growth',name:'Growth',price:2999,upto:25,services:['onboarding','attendance','leave','payroll','relations','exit']},{id:'pro',name:'Pro',price:5999,upto:60,services:['onboarding','attendance','leave','payroll','compliance','performance','relations','exit']}];
  const partners=[{id:'p1',name:'Pooja Menon',phone:'9833300001',email:'pooja@salon10x.in',active:true,cap:12},{id:'p2',name:'Sahil Arora',phone:'9833300002',email:'sahil@salon10x.in',active:true,cap:12},{id:'p3',name:'Farah Siddiqui',phone:'9833300003',email:'farah@salon10x.in',active:true,cap:10}];
  const T=[['AURA01','Aura Salon & Spa','Mumbai','Maharashtra','growth',2,6,'p1','Active','2026-08-01',['compliance'],'Neha Kapoor','9820000000'],
   ['GLOW02','Glow Studio','Pune','Maharashtra','starter',1,4,'p1','Active','2026-10-10',[],'Asha Kulkarni','9820000002'],
   ['VELV03','Velvet Hair Lounge','Bengaluru','Karnataka','pro',3,28,'p2','Active','2026-06-15',['bgv'],'Karthik Rao','9820000003'],
   ['SAFF04','Saffron Beauty Bar','Jaipur','Rajasthan','growth',1,12,'p3','Active','2026-07-20',['compliance'],'Meera Shekhawat','9820000004'],
   ['TRES05','Tresses & Co','Hyderabad','Telangana','growth',2,17,'p2','Active','2026-05-02',['performance'],'Anil Reddy','9820000005'],
   ['BLOM06','Bloom Bridal Studio','Lucknow','Uttar Pradesh','starter',1,7,'p3','Active','2026-09-05',[],'Sana Rizvi','9820000006'],
   ['URBN07','Urban Mane','Delhi','Delhi','pro',4,46,'p2','Active','2026-04-11',['bgv','recruitment'],'Rohit Malhotra','9820000007'],
   ['KESH08','Kesh Kala Salon','Kolkata','West Bengal','starter',1,5,'p3','Onboarding',todayS.slice(0,8)+'01',[],'Rina Das','9820000008'],
   ['NAIL09','Polished Nail Studio','Ahmedabad','Gujarat','starter',1,3,'p1','Active','2026-09-28',[],'Hetal Shah','9820000009'],
   ['GROM10','The Grooming Room','Chennai','Tamil Nadu','growth',2,15,'p3','Suspended','2026-03-14',[],'Vignesh Kumar','9820000010'],
   ['SILK11','Silk Route Salon','Kochi','Kerala','growth',1,11,null,'Onboarding',addDays(todayS,-3),[],'Anitha Nair','9820000011']];
  const tenants=T.map(t=>{const p=plans.find(x=>x.id===t[4]);return{id:t[0],salon:t[1],legal:t[1]+' Pvt. Ltd.',city:t[2],state:t[3],plan:t[4],branches:t[5],staff:t[6],partner:t[7],status:t[8],since:t[9],addons:t[10],services:[...new Set([...p.services,...t[10]])],owner:t[11],ownerPhone:t[12],gstin:'',managers:Math.max(0,t[5]-1)}});
  const inv=[];tenants.filter(t=>t.status!=='Onboarding').forEach((t,i)=>[-2,-1].forEach(k=>{const mk=mkShift(curMK,k);if(t.since.slice(0,7)>mk)return;const amt=monthly(t,plans);inv.push({id:'INV-'+mk.replace('-','')+'-'+t.id,tenant:t.id,mk,amount:amt,gst:Math.round(amt*.18),due:mkShift(mk,1)+'-07',status:k===-2?'Paid':(i%5===2?'Overdue':'Paid'),paidOn:k===-2?mkShift(mk,1)+'-05':(i%5===2?'':mkShift(mk,1)+'-06')})}));
  const leads=[['Mehendi & More','Rekha Joshi','9876500001','Indore','Madhya Pradesh','1','10–19','Payroll & payslips, PF / ESI compliance','New',0],['Crown Unisex Salon','Imtiaz Ali','9876500002','Bhopal','Madhya Pradesh','2–3','20–49','Complete HR outsourcing','Contacted',2],['Hair Theory','Nikita Bose','9876500003','Kolkata','West Bengal','1','1–9','HRMS platform','Demo scheduled',4],['Bliss Spa','Arjun Pillai','9876500004','Trivandrum','Kerala','2–3','10–19','HRMS platform, Background verification','Proposal sent',6],['Mane Street','Tanya Sethi','9876500005','Gurugram','Haryana','4–10','50+','Complete HR outsourcing, Recruitment','Proposal sent',9],['Studio Shringar','Pallavi Desai','9876500006','Surat','Gujarat','1','10–19','Payroll & payslips','Won',12],['Fade Factory','Harsh Vardhan','9876500007','Chandigarh','Chandigarh','1','1–9','HRMS platform','Lost',15],['Ruby Beauty Lounge','Komal Gupta','9876500008','Nagpur','Maharashtra','1','1–9','Recruitment','New',1],['Glam Garage','Siddharth Jain','9876500009','Noida','Uttar Pradesh','2–3','20–49','PF / ESI compliance','Contacted',3],['Ivory Bridal','Shreya Kapoor','9876500010','Amritsar','Punjab','1','10–19','HRMS platform, Payroll & payslips','Demo scheduled',5]]
   .map((l,i)=>({id:'L'+(101+i),salon:l[0],name:l[1],mobile:l[2],city:l[3],state:l[4],branches:l[5],staff:l[6],interests:l[7],stage:l[8],at:addDays(todayS,-l[9])+'T1'+(i%9)+':20:00',owner:i%2?'Super Admin':'Super Admin',notes:[],next:l[8]==='Demo scheduled'?addDays(todayS,2):''}));
  const reqs=[['AURA01','service','Add Recruitment & Sourcing','Need 2 senior stylists for the Bandra branch before Christmas.','Open',1],['VELV03','hr','Disciplinary issue','Stylist shared client numbers on WhatsApp. Need show-cause draft.','In progress',2],['SAFF04','hr','PF / ESI','We crossed 12 staff. Is ESI registration needed now?','Open',0],['TRES05','hr','Letter or document','Increment letters for 5 stylists from December.','Resolved',6],['URBN07','tech','Login help','Manager at Saket branch cannot receive OTP.','Open',0],['GLOW02','service','Add PF, ESI & Labour Law Compliance','Want to start PF voluntarily from next month.','Open',3],['BLOM06','hr','Exit or F&F','Beautician resigned with 3 days notice. How to settle?','In progress',1],['NAIL09','hr','Hiring a new staff member','Looking for a nail technician with gel extension skills.','Open',4]]
   .map((r,i)=>({id:'R-'+(2001+i),tenant:r[0],type:r[1],title:r[2],note:r[3],status:r[4],at:addDays(todayS,-r[5])+'T11:00:00',msgs:[]}));
  const comp=[];
  return{v:1,plans,addons:[{id:'compliance',name:'PF & ESI management',price:49,per:'employee / month'},{id:'bgv',name:'Background verification',price:1199,per:'check (Standard)'},{id:'recruitment',name:'Recruitment',price:4999,per:'hire'},{id:'performance',name:'Performance & incentives',price:499,per:'salon / month'}],
   partners,tenants,invoices:inv,leads,reqs,comp,audit:[],ui:{user:null,view:'overview',tab:{}}};
}
function monthly(t,plans){const p=(plans||S.plans).find(x=>x.id===t.plan);let a=p.price;if(t.addons.includes('compliance'))a+=49*t.staff;if(t.addons.includes('performance'))a+=499;return a}
const T=id=>S.tenants.find(t=>t.id===id);const PT=id=>S.partners.find(p=>p.id===id);
const me=()=>S.ui.user==='super'?{id:'super',name:'Super Admin',role:'Super admin'}:(()=>{const p=PT(S.ui.user);return p?{id:p.id,name:p.name,role:'HR partner'}:null})();
const isSuper=()=>S.ui.user==='super';
const myT=()=>S.tenants.filter(t=>isSuper()||t.partner===S.ui.user);
const audit=(text)=>{S.audit.unshift({at:new Date().toISOString(),by:me()?me().name:'System',text});S.audit.length=Math.min(S.audit.length,300)};

/* compliance calendar for current month */
function compFor(t){const items=[];const pm=mname(mkShift(curMK,-1)).split(' ')[0];if(['Active'].includes(t.status)){items.push(['salary',pm+' salary paid & payslips released',curMK+'-07']);if(t.services.includes('compliance')){items.push(['pf',pm+' PF ECR filed & paid',curMK+'-15']);if(t.staff>=10||t.addons.includes('compliance'))items.push(['esi',pm+' ESIC contribution paid',curMK+'-15'])}
  if(['Maharashtra','Karnataka','Telangana','Gujarat','West Bengal','Tamil Nadu','Kerala','Madhya Pradesh'].includes(t.state))items.push(['pt',pm+' professional tax ('+t.state+')',curMK+'-'+(t.state==='Maharashtra'?'28':'20')])}
  return items.map(i=>{const k=t.id+'|'+curMK+'|'+i[0];const done=S.comp.find(c=>c.k===k);return{k,t,label:i[1],due:i[2],done}})}

if(!S||S.v!==1){S=seed();S.tenants.flatMap(compFor).forEach((c,i)=>{if(c.due<todayS&&i%6!==3)S.comp.push({k:c.k,at:addDays(c.due,-1)+'T17:00:00',by:c.t.partner?PT(c.t.partner).name:'Super Admin'})});save()}
/* ================= RENDER ================= */
const VIEWS={},ACT={},CH={};
const head=(t,sub,right)=>`<div class="row" style="margin-bottom:16px"><div class="sp"><h1>${esc(t)}</h1>${sub?`<div class="sub">${sub}</div>`:''}</div>${right||''}</div>`;
const tabs=(key,list)=>{const cur=S.ui.tab[key]||list[0][0];return[`<div class="tabs">${list.map(([k,l])=>`<button class="${k===cur?'on':''}" data-act="tab" data-k="${key}" data-v="${k}">${esc(l)}</button>`).join('')}</div>`,cur]};
function openModal(h,mount){$('#mbody').innerHTML=h;$('#modal').hidden=false;if(mount)mount();$('#modal').scrollTop=0}
function closeModal(){$('#modal').hidden=true}
function render(){if(!me())return renderLogin();const u=me();
  const openReq=S.reqs.filter(r=>r.status!=='Resolved'&&myT().some(t=>t.id===r.tenant)).length;
  const pendComp=myT().flatMap(compFor).filter(c=>!c.done).length;
  const NAV=[['overview','Overview',0,1],['salons','Salons',myT().filter(t=>t.status==='Onboarding').length,1],['opps','Opportunities',myT().reduce((a,t)=>a+ideas(t).length,0),1],['jobs','Job openings',S.jobs.filter(j=>j.status==='Open'&&myT().some(t=>t.id===j.tenant)).length,1],['talent','Talent pool',0,1],['directory','Directory',0,isSuper()],['vwh','Verified work history',S.vwh?S.vwh.filter(yearDue).length:0,isSuper()],['ann','Announcements',0,isSuper()],['leads','Sales leads',S.leads.filter(l=>l.stage==='New').length,isSuper()],['requests','Requests & support',openReq,1],['compliance','Compliance calendar',pendComp,1],['billing','Billing',S.invoices.filter(i=>i.status==='Overdue').length,isSuper()],['partners','HR partners',0,isSuper()],['plans','Plans & pricing',0,isSuper()],['audit','Audit log',0,isSuper()]].filter(n=>n[3]);
  if(!NAV.some(n=>n[0]===S.ui.view))S.ui.view='overview';
  $('#app').innerHTML=`<div class="wrap"><aside class="rail"><div class="brand"><i></i><div>Salon HR<small>Console · ${esc(u.role)}</small></div></div><nav class="nav">${NAV.map(n=>`<button class="${S.ui.view===n[0]?'on':''}" data-act="go" data-v="${n[0]}">${esc(n[1])}${n[2]?`<span class="badge">${n[2]}</span>`:''}</button>`).join('')}</nav><div class="navsec">Demo data · stays in this browser</div></aside>
  <main><div class="top"><div></div><div class="who">${chip(u.role,isSuper()?'c-b':'c-info')}<span class="small muted">${esc(u.name)}</span><a class="btn s" href="#home">Website</a><button class="btn s" data-act="logout">Log out</button></div></div>${VIEWS[S.ui.view]()}</main></div>`;save()}
function renderLogin(){const st=S.ui.login||{};const ppl=[{id:'super',name:'Super Admin',title:'Salon HR · all salons',phone:'9800000999'},...S.partners.filter(p=>p.active).map(p=>({id:p.id,name:p.name,title:'HR partner · '+S.tenants.filter(t=>t.partner===p.id).length+' salons',phone:p.phone}))];
  $('#app').innerHTML=`<div class="elogin"><div class="brand" style="color:var(--ink);justify-content:center;font-size:26px"><i></i><div>Salon HR<small style="color:var(--mute);opacity:1">Internal console</small></div></div>
  <div class="card" style="margin-top:22px">${!st.id?`<h2>Team login</h2><p class="sub">For the Salon HR team only. Use your registered mobile.</p><form id="flog" style="margin-top:14px"><label class="f">Mobile<input name="m" inputmode="tel"></label><button class="btn p" style="width:100%;margin-top:12px">Send OTP</button></form>`:`<h2>Enter OTP</h2><p class="sub">Sent to ${esc(st.phone)}. Demo OTP: 123456</p><form id="fotp" style="margin-top:14px"><label class="f">OTP<input name="o" inputmode="numeric" maxlength="6"></label><button class="btn p" style="width:100%;margin-top:12px">Verify</button></form><button class="btn" style="width:100%;margin-top:8px" data-act="lback">Change number</button>`}</div>
  ${!st.id?`<div class="card"><h3>Demo logins — tap to fill</h3><div class="list" style="margin-top:6px">${ppl.map(x=>`<div class="click" data-act="lfill" data-id="${x.id}" style="cursor:pointer"><span class="sp"><b>${esc(x.name)}</b><br><span class="small muted">${esc(x.title)}</span></span><span class="small">${x.phone}</span></div>`).join('')}</div></div>`:''}<p style="text-align:center"><a href="#login">← Back to Salon HR login</a></p></div>`;save()}
const phoneOf=id=>id==='super'?'9800000999':(PT(id)||{}).phone;

/* ================= OVERVIEW ================= */
VIEWS.overview=()=>{const ts=myT(),act=ts.filter(t=>t.status==='Active');const staff=act.reduce((a,t)=>a+t.staff,0),mrr=act.reduce((a,t)=>a+monthly(t),0);
  const reqs=S.reqs.filter(r=>r.status!=='Resolved'&&ts.some(t=>t.id===r.tenant));const comp=ts.flatMap(compFor).filter(c=>!c.done).sort((a,b)=>a.due<b.due?-1:1);
  const leadsM=S.leads.filter(l=>l.at.slice(0,7)===curMK).length;const overdue=S.invoices.filter(i=>i.status==='Overdue');
  return head(isSuper()?'Salon HR at a glance':'My salons',isSuper()?'Every salon, lead, invoice and request on the platform.':'Only the salons assigned to you.')+
  `<div class="grid g4" style="margin-bottom:16px"><div class="kpi"><b>${act.length}</b><span>Active salons${ts.length>act.length?' · '+(ts.length-act.length)+' other':''}</span></div><div class="kpi"><b>${staff}</b><span>Staff on HRMS</span></div>${isSuper()?`<div class="kpi"><b>${inr(mrr)}</b><span>Monthly recurring revenue (excl. GST)</span></div><div class="kpi"><b>${leadsM}</b><span>New leads this month</span></div>`:`<div class="kpi"><b>${reqs.length}</b><span>Open requests</span></div><div class="kpi"><b>${comp.length}</b><span>Compliance tasks pending</span></div>`}</div>
  <div class="grid g2"><div class="card"><h2>Requests waiting</h2>${reqs.length?`<div class="list">${reqs.slice(0,6).map(r=>`<div class="click" data-act="req" data-id="${r.id}" style="cursor:pointer"><span class="sp"><b>${esc(r.title)}</b><br><span class="small muted">${esc(T(r.tenant).salon)} · ${fdate(r.at)}</span></span>${chip(r.status,r.status==='Open'?'c-warn':'c-info')}</div>`).join('')}</div>`:'<div class="empty">Nothing waiting.</div>'}</div>
  <div class="card"><h2>Compliance due this month</h2>${comp.length?`<div class="list">${comp.slice(0,7).map(c=>`<div><span class="sp"><b>${esc(c.label)}</b><br><span class="small muted">${esc(c.t.salon)}</span></span>${chip('Due '+fdate(c.due),c.due<todayS?'c-bad':'c-warn')}</div>`).join('')}</div>`:'<div class="empty">All filed for this month.</div>'}</div></div>
  ${isSuper()?`<div class="grid g2"><div class="card"><h2>Pipeline</h2><div class="bars">${STAGES.map(s=>{const n=S.leads.filter(l=>l.stage===s).length;return`<div class="r"><span>${s}</span><div class="t"><i style="width:${Math.min(100,n*25)}%;background:${s==='Won'?'var(--ok)':s==='Lost'?'var(--bad)':'var(--berry)'}"></i></div><b class="n">${n}</b></div>`}).join('')}</div></div>
  <div class="card"><h2>Partner load</h2><div class="bars">${S.partners.map(p=>{const n=S.tenants.filter(t=>t.partner===p.id).length;return`<div class="r"><span>${esc(p.name.split(' ')[0])}</span><div class="t"><i style="width:${n/p.cap*100}%"></i></div><b class="n">${n}/${p.cap}</b></div>`}).join('')}</div>${S.tenants.some(t=>!t.partner)?`<p class="small" style="margin-top:10px">${chip(S.tenants.filter(t=>!t.partner).length+' salon(s) without an HR partner','c-bad')}</p>`:''}${overdue.length?`<p class="small" style="margin-top:6px">${chip(overdue.length+' overdue invoice(s)','c-bad')}</p>`:''}</div></div>`:''}`};

/* ================= SALONS ================= */
VIEWS.salons=()=>{const q=(S.ui.tab.q||'').toLowerCase();const st=S.ui.tab.st||'all';const L=myT().filter(t=>(st==='all'||t.status===st)&&(!q||(t.salon+' '+t.id+' '+t.city+' '+t.owner).toLowerCase().includes(q)));
  return head('Salons',`${myT().length} ${isSuper()?'on the platform':'assigned to you'} · each salon is a separate, isolated account`,isSuper()?`<button class="btn p" data-act="addT">Onboard a salon</button>`:'')+
  `<div class="card"><div class="row" style="margin-bottom:10px"><select data-change="tst" style="width:auto">${['all','Onboarding','Active','Suspended','Churned'].map(x=>`<option value="${x}"${x===st?' selected':''}>${x==='all'?'All statuses':x}</option>`).join('')}</select><input type="search" placeholder="Search salon, ID, city or owner" value="${esc(S.ui.tab.q||'')}" data-change="tq" style="max-width:320px"></div>
  <div class="scroll"><table class="stack"><thead><tr><th>Salon</th><th>Owner</th><th>Plan</th><th class="n">Branches</th><th class="n">Staff</th><th>HR partner</th>${isSuper()?'<th class="n">Monthly</th>':''}<th>Status</th></tr></thead><tbody>${L.map(t=>`<tr class="click" data-act="ten" data-id="${t.id}"><td><b>${esc(t.salon)}</b><br><span class="small muted">${t.id} · ${esc(t.city)}</span></td><td>${esc(t.owner)}<br><span class="small muted">${t.ownerPhone}</span></td><td>${esc(S.plans.find(p=>p.id===t.plan).name)}${t.addons.length?'<br><span class="small muted">+'+t.addons.length+' add-on(s)</span>':''}</td><td class="n">${t.branches}</td><td class="n">${t.staff}</td><td>${t.partner?esc(PT(t.partner).name):chip('Unassigned','c-bad')}</td>${isSuper()?`<td class="n">${inr(monthly(t))}</td>`:''}<td>${chip(t.status,TSTC[t.status])}</td></tr>`).join('')||'<tr><td colspan="8" class="muted">No salons match.</td></tr>'}</tbody></table></div></div>`};
CH.tst=el=>{S.ui.tab.st=el.value;render()};CH.tq=el=>{S.ui.tab.q=el.value;render()};
ACT.ten=el=>tenModal(el.dataset.id);
function tenModal(id,tab){const t=T(id);S.ui.tab.ten=tab||S.ui.tab.ten||'ov';const [tb,cur]=tabs('ten',[['ov','Overview'],['svc','Plan & services'],['users','Logins'],...(isSuper()?[['bill','Billing']]:[]),['req','Requests'],['support','Support access']]);let b='';
  if(cur==='ov')b=`<form id="ften" class="fg"><label class="f">Brand name<input name="salon" value="${esc(t.salon)}" ${isSuper()?'':'disabled'}></label><label class="f">Legal entity<input name="legal" value="${esc(t.legal)}" ${isSuper()?'':'disabled'}></label><label class="f">GSTIN<input name="gstin" value="${esc(t.gstin)}" ${isSuper()?'':'disabled'}></label><label class="f">City<input name="city" value="${esc(t.city)}" ${isSuper()?'':'disabled'}></label><label class="f">State<input name="state" value="${esc(t.state)}" ${isSuper()?'':'disabled'}></label><label class="f">Branches<input type="number" name="branches" value="${t.branches}" ${isSuper()?'':'disabled'}></label><label class="f">Staff on HRMS<input type="number" name="staff" value="${t.staff}" disabled></label><label class="f">Client since<input value="${fdate(t.since)}" disabled></label>
    <label class="f">HR partner<select name="partner" ${isSuper()?'':'disabled'}><option value="">Unassigned</option>${S.partners.filter(p=>p.active).map(p=>`<option value="${p.id}"${p.id===t.partner?' selected':''}>${esc(p.name)} (${S.tenants.filter(x=>x.partner===p.id).length}/${p.cap})</option>`).join('')}</select></label>
    <label class="f">Status<select name="status" ${isSuper()?'':'disabled'}>${['Onboarding','Active','Suspended','Churned'].map(s=>`<option${s===t.status?' selected':''}>${s}</option>`).join('')}</select></label>${isSuper()?'<div style="align-self:end"><button class="btn p">Save</button></div>':''}</form>
    ${t.status==='Onboarding'?`<div class="note" style="margin-top:12px"><b>Onboarding checklist:</b> owner invite sent · branches & shifts set up · leave types & pay rules · staff invited · first payroll run with the HR partner.</div>`:''}`;
  if(cur==='svc'){const p=S.plans.find(x=>x.id===t.plan);b=`<div class="row" style="margin-bottom:12px"><label class="f" style="width:auto">Plan<select data-change="tplan" data-id="${t.id}" ${isSuper()?'':'disabled'} style="width:auto">${S.plans.map(x=>`<option value="${x.id}"${x.id===t.plan?' selected':''}>${esc(x.name)} · ${inr(x.price)}/month · up to ${x.upto} staff</option>`).join('')}</select></label>${t.staff>p.upto?chip('Over plan limit — suggest upgrade','c-bad'):''}</div>
    <p class="sub" style="margin-bottom:8px">Ticked services appear as "Active" in the salon's portal and unlock that module in their HRMS. Services in the plan are included; anything else is billed as an add-on.</p><div class="grid g2">${SVC.map(s=>{const inPlan=p.services.includes(s[0]),on=t.services.includes(s[0]);return`<label class="chk"><input type="checkbox" data-change="tsvc" data-id="${t.id}" data-s="${s[0]}" ${on?'checked':''} ${inPlan||!isSuper()?'disabled':''}> ${esc(s[1])} ${inPlan?chip('In plan','c-ok'):on?chip('Add-on','c-info'):''}</label>`}).join('')}</div>${isSuper()?'':'<p class="small muted" style="margin-top:10px">Only the super admin changes plans and services. Raise it from the salon\'s request.</p>'}`}
  if(cur==='users')b=`<table class="stack"><thead><tr><th>Person</th><th>Role</th><th>Mobile</th><th>Access</th><th></th></tr></thead><tbody><tr><td><b>${esc(t.owner)}</b></td><td>Owner</td><td>${t.ownerPhone}</td><td>All branches, all modules</td><td>${isSuper()?`<button class="btn s" data-act="ownerPh" data-id="${t.id}">Change owner mobile</button>`:''} <button class="btn s" data-act="invite" data-id="${t.id}">Resend invite</button></td></tr>${t.managers?`<tr><td colspan="5" class="small muted">${t.managers} manager login(s) created by the owner in their HRMS (Branches & managers).</td></tr>`:''}<tr><td colspan="5" class="small muted">${t.staff} staff log in to the staff app with their own mobile + OTP. Logins are unique per salon; a mobile can be active in only one salon at a time.</td></tr></tbody></table>`;
  if(cur==='bill'){const iv=S.invoices.filter(i=>i.tenant===t.id).sort((a,b)=>a.mk<b.mk?1:-1);b=`<div class="list"><div><span class="sp">Current monthly charge (excl. GST)</span><b>${inr(monthly(t))}</b></div></div>${invTable(iv,false)}`}
  if(cur==='req'){const rs=S.reqs.filter(r=>r.tenant===t.id);b=reqTable(rs,false)}
  if(cur==='support')b=`<p>Open this salon's HRMS admin to help the owner — fix a punch, set up a shift, run payroll with them.</p><div class="note i" style="margin:12px 0">Every support session is logged with your name and time, and the owner sees a "Salon HR support is viewing your account" banner. ${isSuper()?'':'You can only open salons assigned to you.'}</div>${t.id==='AURA01'?`<a class="btn p" href="#app-admin" data-act="support" data-id="${t.id}">Open ${esc(t.salon)} admin as support</a>`:`<button class="btn p" disabled>Open ${esc(t.salon)} admin as support</button><p class="small muted" style="margin-top:10px">In this demo only Aura Salon & Spa (AURA01) has a live salon admin. In the live platform every salon opens its own account.</p>`}`;
  openModal(`<h2>${esc(t.salon)}</h2><p class="sub">${t.id} · ${esc(t.city)}, ${esc(t.state)} · ${chip(t.status,TSTC[t.status])}</p>${tb}<div>${b}</div>`,()=>{
    document.querySelectorAll('#mbody .tabs button').forEach(x=>x.onclick=()=>tenModal(id,x.dataset.v));
    const f=$('#ften');if(f&&isSuper())f.onsubmit=ev=>{ev.preventDefault();['salon','legal','gstin','city','state'].forEach(k=>t[k]=fv(f,k));t.branches=+fv(f,'branches')||1;const op=t.partner;t.partner=fv(f,'partner')||null;t.status=fv(f,'status');if(op!==t.partner)audit(`Assigned ${t.salon} to ${t.partner?PT(t.partner).name:'nobody'}`);audit('Updated salon '+t.salon);render();tenModal(id,'ov');toast('Saved')}})}
CH.tplan=el=>{const t=T(el.dataset.id);t.plan=el.value;const p=S.plans.find(x=>x.id===t.plan);t.services=[...new Set([...p.services,...t.addons])];audit(`${t.salon} moved to ${p.name} plan`);render();tenModal(t.id,'svc');toast('Plan updated — salon portal and HRMS modules updated')};
CH.tsvc=el=>{const t=T(el.dataset.id),s=el.dataset.s;if(el.checked){t.addons.push(s);t.services.push(s)}else{t.addons=t.addons.filter(x=>x!==s);t.services=t.services.filter(x=>x!==s)}audit(`${el.checked?'Enabled':'Disabled'} ${svcName(s)} for ${t.salon}`);render();tenModal(t.id,'svc')};
ACT.invite=el=>{const t=T(el.dataset.id);audit('Resent owner invite to '+t.salon);toast('Invite sent to '+t.owner+' by SMS & WhatsApp')};
ACT.ownerPh=el=>{const t=T(el.dataset.id);openModal(`<h2>Change owner mobile — ${esc(t.salon)}</h2><p class="sub">Use only after verifying the owner's identity (e.g. a call from the registered email). The old number loses access immediately.</p><form id="fph"><label class="f">New mobile<input name="m" inputmode="tel"></label><label class="f" style="margin-top:10px">Verification note<input name="n" placeholder="Verified via call + email from registered address"></label><button class="btn p" style="margin-top:12px">Change</button></form>`,()=>{$('#fph').onsubmit=ev=>{ev.preventDefault();const m=fv($('#fph'),'m').replace(/\D/g,'').slice(-10),n=fv($('#fph'),'n');if(!/^[6-9]\d{9}$/.test(m)||!n)return toast('Valid mobile and a verification note needed');audit(`Owner mobile of ${t.salon} changed (${n})`);t.ownerPhone=m;tenModal(t.id,'users');toast('Owner mobile changed')}})};
ACT.support=el=>{const t=T(el.dataset.id);audit('Support session opened for '+t.salon);save();if(PLATFORM.apps.hrms)PLATFORM.apps.hrms.support(me().name)};
ACT.addT=(el,prefill)=>{const l=prefill||{};openModal(`<h2>Onboard a salon</h2><p class="sub">Creates the salon's own account, sends the owner an invite and assigns an HR partner.</p><form id="fadd" class="fg">
  <label class="f">Brand name *<input name="salon" value="${esc(l.salon)}"></label><label class="f">Legal entity<input name="legal" value="${esc(l.salon?l.salon+' Pvt. Ltd.':'')}"></label><label class="f">City *<input name="city" value="${esc(l.city)}"></label><label class="f">State<input name="state" value="${esc(l.state)}"></label>
  <label class="f">Owner name *<input name="owner" value="${esc(l.name)}"></label><label class="f">Owner mobile *<input name="ph" value="${esc(l.mobile)}" inputmode="tel"></label><label class="f">Branches<input type="number" name="br" min="1" value="${parseInt(l.branches)||1}"></label><label class="f">Expected staff<input type="number" name="st" min="1" value="${parseInt(l.staff)||5}"></label>
  <label class="f">Plan<select name="plan">${S.plans.map(p=>`<option value="${p.id}">${esc(p.name)} · ${inr(p.price)}/month</option>`).join('')}</select></label><label class="f">HR partner<select name="partner">${S.partners.filter(p=>p.active).map(p=>`<option value="${p.id}">${esc(p.name)} (${S.tenants.filter(x=>x.partner===p.id).length}/${p.cap})</option>`).join('')}</select></label>
  <div style="grid-column:1/-1"><button class="btn p">Create salon & send owner invite</button></div></form>`,()=>{$('#fadd').onsubmit=ev=>{ev.preventDefault();const f=$('#fadd');const ph=fv(f,'ph').replace(/\D/g,'').slice(-10);if(!fv(f,'salon')||!fv(f,'city')||!fv(f,'owner')||!/^[6-9]\d{9}$/.test(ph))return toast('Brand, city, owner and a valid mobile are required');
    const base=fv(f,'salon').replace(/[^A-Za-z]/g,'').toUpperCase().slice(0,4).padEnd(4,'X');const id=base+pad(S.tenants.length+1);const p=S.plans.find(x=>x.id===fv(f,'plan'));
    S.tenants.push({id,salon:fv(f,'salon'),legal:fv(f,'legal'),city:fv(f,'city'),state:fv(f,'state'),plan:p.id,branches:+fv(f,'br')||1,staff:+fv(f,'st')||1,partner:fv(f,'partner'),status:'Onboarding',since:todayS,addons:[],services:p.services.slice(),owner:fv(f,'owner'),ownerPhone:ph,gstin:'',managers:0});
    if(l.id){const ld=S.leads.find(x=>x.id===l.id);ld.stage='Won';ld.tenant=id}
    audit(`Onboarded ${fv(f,'salon')} (${id}) on ${p.name}; invite sent to owner`);closeModal();S.ui.view='salons';render();toast(`${id} created — owner invite sent`)}})};

/* ================= LEADS ================= */
VIEWS.leads=()=>{const st=S.ui.tab.ls||'open';const L=S.leads.filter(l=>st==='all'||(st==='open'?!['Won','Lost'].includes(l.stage):l.stage===st)).sort((a,b)=>a.at<b.at?1:-1);
  return head('Sales leads','Every enquiry from the website form and "Talk To Your HR" call-backs lands here, and also in partners@salon10x.in.',`<button class="btn p" data-act="addL">Add lead</button>`)+
  `<div class="grid g4" style="margin-bottom:14px">${['New','Demo scheduled','Proposal sent','Won'].map(s=>`<div class="kpi"><b>${S.leads.filter(l=>l.stage===s).length}</b><span>${s}</span></div>`).join('')}</div>
  <div class="card"><div class="row" style="margin-bottom:10px"><select data-change="ls" style="width:auto">${[['open','Open leads'],['all','All'],...STAGES.map(s=>[s,s])].map(o=>`<option value="${o[0]}"${o[0]===st?' selected':''}>${o[1]}</option>`).join('')}</select></div>
  <div class="scroll"><table class="stack"><thead><tr><th>Salon</th><th>Contact</th><th>Size</th><th>Interested in</th><th>Received</th><th>Stage</th><th></th></tr></thead><tbody>${L.map(l=>`<tr><td><b>${esc(l.salon)}</b><br><span class="small muted">${esc(l.city)}${l.state?', '+esc(l.state):''}</span></td><td>${esc(l.name)}<br><span class="small muted">${l.mobile}</span></td><td class="small">${esc(l.branches)} branch · ${esc(l.staff)} staff</td><td class="small">${esc(l.interests)}</td><td class="small">${fdate(l.at)}</td><td><select data-change="lstage" data-id="${l.id}" style="width:auto;min-height:34px;padding:4px 8px;font-size:13px">${STAGES.map(s=>`<option${s===l.stage?' selected':''}>${s}</option>`).join('')}</select>${l.next?`<br><span class="small muted">Next: ${fdate(l.next)}</span>`:''}</td><td>${l.tenant?chip('Salon '+l.tenant,'c-ok'):l.stage!=='Lost'?`<button class="btn s" data-act="convert" data-id="${l.id}">Convert to salon</button>`:''}</td></tr>`).join('')}</tbody></table></div></div>`};
CH.ls=el=>{S.ui.tab.ls=el.value;render()};
CH.lstage=el=>{const l=S.leads.find(x=>x.id===el.dataset.id);l.stage=el.value;audit(`Lead ${l.salon} → ${l.stage}`);if(l.stage==='Won'&&!l.tenant)return ACT.addT(null,l);render()};
ACT.convert=el=>ACT.addT(null,S.leads.find(x=>x.id===el.dataset.id));
ACT.addL=()=>openModal(`<h2>Add lead</h2><form id="fl" class="fg"><label class="f">Salon *<input name="s"></label><label class="f">Contact *<input name="n"></label><label class="f">Mobile *<input name="m" inputmode="tel"></label><label class="f">City<input name="c"></label><label class="f">Staff<select name="st"><option>1–9</option><option>10–19</option><option>20–49</option><option>50+</option></select></label><label class="f">Interested in<input name="i"></label><div><button class="btn p">Add</button></div></form>`,()=>{$('#fl').onsubmit=ev=>{ev.preventDefault();const f=$('#fl');if(!fv(f,'s')||!fv(f,'n')||!fv(f,'m'))return toast('Salon, contact and mobile needed');S.leads.push({id:'L'+(101+S.leads.length),salon:fv(f,'s'),name:fv(f,'n'),mobile:fv(f,'m'),city:fv(f,'c'),state:'',branches:'1',staff:fv(f,'st'),interests:fv(f,'i'),stage:'New',at:new Date().toISOString(),notes:[]});audit('Added lead '+fv(f,'s'));closeModal();render()}});

/* ================= REQUESTS ================= */
function reqTable(rs,showSalon=true){return rs.length?`<table class="stack"><thead><tr><th>Request</th>${showSalon?'<th>Salon</th><th>HR partner</th>':''}<th>Type</th><th>Raised</th><th>Status</th></tr></thead><tbody>${rs.sort((a,b)=>(a.status==='Resolved')-(b.status==='Resolved')||(a.at<b.at?1:-1)).map(r=>{const t=T(r.tenant),age=(Date.now()-new Date(r.at))/864e5;return`<tr class="click" data-act="req" data-id="${r.id}"><td><b>${esc(r.title)}</b><br><span class="small muted">${r.id}</span></td>${showSalon?`<td>${esc(t.salon)}</td><td>${t.partner?esc(PT(t.partner).name):chip('Unassigned','c-bad')}</td>`:''}<td>${chip(r.type==='service'?'Add service':r.type==='tech'?'Technical':'HR help',r.type==='service'?'c-b':r.type==='tech'?'c-info':'')}</td><td class="small">${fdate(r.at)}${r.status!=='Resolved'&&age>2?'<br>'+chip('Over 48h','c-bad'):''}</td><td>${chip(r.status,r.status==='Open'?'c-warn':r.status==='Resolved'?'c-ok':'c-info')}</td></tr>`}).join('')}</tbody></table>`:'<div class="empty">No requests.</div>'}
VIEWS.requests=()=>{const st=S.ui.tab.rs||'open';const rs=S.reqs.filter(r=>myT().some(t=>t.id===r.tenant)&&(st==='all'||(st==='open'?r.status!=='Resolved':r.type===st)));
  return head('Requests & support','Service add-on requests, HR help and technical issues raised by salons from their portal. 48-hour response target.')+`<div class="card"><div class="row" style="margin-bottom:10px"><select data-change="rs" style="width:auto">${[['open','Open'],['all','All'],['service','Add service'],['hr','HR help'],['tech','Technical']].map(o=>`<option value="${o[0]}"${o[0]===st?' selected':''}>${o[1]}</option>`).join('')}</select></div>${reqTable(rs)}</div>`};
CH.rs=el=>{S.ui.tab.rs=el.value;render()};
ACT.req=el=>{const r=S.reqs.find(x=>x.id===el.dataset.id),t=T(r.tenant);openModal(`<h2>${esc(r.title)}</h2><p class="sub">${r.id} · ${esc(t.salon)} (${t.id}) · raised ${fdt(r.at)} · ${chip(r.status)}</p><div class="note i" style="margin:10px 0">${esc(r.note)}</div>
  <div class="list">${r.msgs.map(m=>`<div><span class="chip c-b">${esc(m.by)}</span><span class="sp">${esc(m.text)}</span><span class="small muted">${fdt(m.at)}</span></div>`).join('')}</div>
  <label class="f" style="margin-top:12px">Reply to the salon<textarea id="rr"></textarea></label><div class="row" style="margin-top:10px">${r.type==='service'&&isSuper()&&r.status!=='Resolved'?`<button class="btn ok" data-act="reqEnable" data-id="${r.id}">Enable service & resolve</button>`:''}<span class="sp"></span><button class="btn" data-act="reqSend" data-id="${r.id}" data-s="In progress">Reply</button><button class="btn p" data-act="reqSend" data-id="${r.id}" data-s="Resolved">Reply & resolve</button></div>`)};
ACT.reqSend=el=>{const r=S.reqs.find(x=>x.id===el.dataset.id),txt=$('#rr').value.trim();if(!txt&&el.dataset.s!=='Resolved')return toast('Write a reply');if(txt)r.msgs.push({by:me().name,at:new Date().toISOString(),text:txt});r.status=el.dataset.s;audit(`Request ${r.id} ${r.status}`);render();ACT.req({dataset:{id:r.id}})};
ACT.reqEnable=el=>{const r=S.reqs.find(x=>x.id===el.dataset.id),t=T(r.tenant);const s=SVC.find(x=>r.title.includes(x[1]));if(s&&!t.services.includes(s[0])){t.services.push(s[0]);t.addons.push(s[0])}r.status='Resolved';r.msgs.push({by:me().name,at:new Date().toISOString(),text:(s?s[1]:'Service')+' is now active for your salon.'});audit(`Enabled ${s?s[1]:'service'} for ${t.salon} from request ${r.id}`);render();toast('Service enabled')};

/* ================= COMPLIANCE ================= */
VIEWS.compliance=()=>{const items=myT().flatMap(compFor).sort((a,b)=>a.due<b.due?-1:a.due>b.due?1:a.t.salon<b.t.salon?-1:1);const done=items.filter(i=>i.done).length;
  return head('Compliance calendar',`${mname(curMK)} · ${done} of ${items.length} done · salary by the 7th, PF and ESI by the 15th, professional tax as per state`)+
  `<div class="card"><table class="stack"><thead><tr><th>Due</th><th>Salon</th><th>Task</th><th>HR partner</th><th>Status</th></tr></thead><tbody>${items.map(i=>`<tr><td>${fdate(i.due)}</td><td><b>${esc(i.t.salon)}</b><br><span class="small muted">${i.t.id}</span></td><td>${esc(i.label)}</td><td class="small">${i.t.partner?esc(PT(i.t.partner).name):'—'}</td><td>${i.done?chip('Done '+fdate(i.done.at)+' · '+i.done.by,'c-ok'):`<button class="btn s ${i.due<todayS?'bad':''}" data-act="compDone" data-k="${esc(i.k)}">${i.due<todayS?'Overdue — mark done':'Mark done'}</button>`}</td></tr>`).join('')}</tbody></table><p class="small muted" style="margin-top:10px">Professional tax dates differ by state; confirm each state's schedule. Mark a task done only after filing and payment are confirmed.</p></div>`};
ACT.compDone=el=>{S.comp.push({k:el.dataset.k,at:new Date().toISOString(),by:me().name});audit('Compliance done: '+el.dataset.k.replace(/\|/g,' · '));render()};

/* ================= BILLING ================= */
function invTable(iv,showSalon=true){return`<table class="stack" style="margin-top:10px"><thead><tr><th>Invoice</th>${showSalon?'<th>Salon</th>':''}<th>Month</th><th class="n">Amount</th><th class="n">GST 18%</th><th class="n">Total</th><th>Due</th><th>Status</th></tr></thead><tbody>${iv.map(i=>`<tr><td class="small">${i.id}</td>${showSalon?`<td>${esc(T(i.tenant).salon)}</td>`:''}<td>${mname(i.mk)}</td><td class="n">${inr(i.amount)}</td><td class="n">${inr(i.gst)}</td><td class="n b">${inr(i.amount+i.gst)}</td><td class="small">${fdate(i.due)}</td><td>${i.status==='Paid'?chip('Paid '+fdate(i.paidOn),'c-ok'):`${chip(i.status,i.status==='Overdue'?'c-bad':'c-warn')} ${isSuper()?`<button class="btn s" data-act="invPaid" data-id="${i.id}">Mark paid</button>`:''}`}</td></tr>`).join('')||'<tr><td colspan="8" class="muted">No invoices.</td></tr>'}</tbody></table>`}
VIEWS.billing=()=>{const iv=S.invoices.slice().sort((a,b)=>a.mk<b.mk?1:a.mk>b.mk?-1:0);const lastMK=mkShift(curMK,-1);const have=S.invoices.some(i=>i.mk===curMK);
  const due=iv.filter(i=>i.status!=='Paid').reduce((a,i)=>a+i.amount+i.gst,0),col=iv.filter(i=>i.status==='Paid'&&i.mk===lastMK).reduce((a,i)=>a+i.amount+i.gst,0);
  return head('Billing','Monthly subscription invoices per salon, with add-ons and GST.',have?chip(mname(curMK)+' invoices generated','c-ok'):`<button class="btn p" data-act="genInv">Generate ${mname(curMK)} invoices</button>`)+
  `<div class="grid g4" style="margin-bottom:14px"><div class="kpi"><b>${inr(S.tenants.filter(t=>t.status==='Active').reduce((a,t)=>a+monthly(t),0))}</b><span>Monthly recurring (excl. GST)</span></div><div class="kpi"><b>${inr(col)}</b><span>Collected for ${mname(lastMK)}</span></div><div class="kpi"><b>${inr(due)}</b><span>Outstanding</span></div><div class="kpi"><b>${S.invoices.filter(i=>i.status==='Overdue').length}</b><span>Overdue invoices</span></div></div><div class="card">${invTable(iv)}</div>`};
ACT.genInv=()=>{let n=0;S.tenants.filter(t=>t.status==='Active').forEach(t=>{const amt=monthly(t);S.invoices.push({id:'INV-'+curMK.replace('-','')+'-'+t.id,tenant:t.id,mk:curMK,amount:amt,gst:Math.round(amt*.18),due:mkShift(curMK,1)+'-07',status:'Due',paidOn:''});n++});audit(`Generated ${n} invoices for ${mname(curMK)}`);render();toast(n+' invoices generated and emailed to owners')};
ACT.invPaid=el=>{const i=S.invoices.find(x=>x.id===el.dataset.id);i.status='Paid';i.paidOn=todayS;audit('Invoice '+i.id+' marked paid');render()};

/* ================= PARTNERS ================= */
VIEWS.partners=()=>head('HR partners','Your HR executives. Each sees only the salons assigned to them.')+
  `<div class="card"><table class="stack"><thead><tr><th>Partner</th><th>Mobile (login)</th><th class="n">Salons</th><th class="n">Open requests</th><th>Assigned salons</th><th>Status</th></tr></thead><tbody>${S.partners.map(p=>{const ts=S.tenants.filter(t=>t.partner===p.id);return`<tr><td><b>${esc(p.name)}</b><br><span class="small muted">${esc(p.email)}</span></td><td>${p.phone}</td><td class="n">${ts.length}/${p.cap}</td><td class="n">${S.reqs.filter(r=>r.status!=='Resolved'&&ts.some(t=>t.id===r.tenant)).length}</td><td class="small">${ts.map(t=>esc(t.salon)).join(', ')||'—'}</td><td><button class="btn s ${p.active?'bad':''}" data-act="pTog" data-id="${p.id}">${p.active?'Deactivate':'Activate'}</button></td></tr>`}).join('')}</tbody></table>
  <form id="fp" class="fg" style="margin-top:14px"><label class="f">Name<input name="n"></label><label class="f">Mobile<input name="m" inputmode="tel"></label><label class="f">Email<input name="e"></label><label class="f">Max salons<input type="number" name="c" value="12"></label><div style="align-self:end"><button class="btn p">Add HR partner</button></div></form></div>
  <div class="card"><h3>Reassign salons</h3><p class="sub" style="margin-bottom:8px">Change the partner for any salon; the new partner gets access instantly and the old one loses it.</p><table class="stack"><tbody>${S.tenants.map(t=>`<tr><td>${esc(t.salon)} <span class="small muted">${t.id}</span></td><td><select data-change="assign" data-id="${t.id}" style="width:auto"><option value="">Unassigned</option>${S.partners.filter(p=>p.active).map(p=>`<option value="${p.id}"${p.id===t.partner?' selected':''}>${esc(p.name)}</option>`).join('')}</select></td></tr>`).join('')}</tbody></table></div>`;
CH.assign=el=>{const t=T(el.dataset.id);t.partner=el.value||null;audit(`Assigned ${t.salon} to ${t.partner?PT(t.partner).name:'nobody'}`);render();toast('Reassigned')};
ACT.pTog=el=>{const p=PT(el.dataset.id);if(p.active&&S.tenants.some(t=>t.partner===p.id))return toast('Reassign their salons first');p.active=!p.active;audit((p.active?'Activated ':'Deactivated ')+p.name);render()};

/* ================= PLANS ================= */
VIEWS.plans=()=>head('Plans & pricing','Sample pricing — set your own. Changes apply to new invoices.')+
  `<div class="grid g3">${S.plans.map((p,i)=>`<div class="card"><input value="${esc(p.name)}" data-change="plE" data-i="${i}" data-k="name" style="font:600 20px Outfit"><div class="fg" style="margin-top:10px"><label class="f">Price / month (₹)<input type="number" value="${p.price}" data-change="plE" data-i="${i}" data-k="price"></label><label class="f">Up to staff<input type="number" value="${p.upto}" data-change="plE" data-i="${i}" data-k="upto"></label></div><p class="small b" style="margin:12px 0 6px">Included services</p>${SVC.map(s=>`<label class="chk"><input type="checkbox" ${p.services.includes(s[0])?'checked':''} data-change="plS" data-i="${i}" data-s="${s[0]}"> ${esc(s[1])}</label>`).join('')}<p class="small muted" style="margin-top:8px">${S.tenants.filter(t=>t.plan===p.id).length} salons on this plan</p></div>`).join('')}</div>
  <div class="card"><h2>Add-ons</h2><table><tbody>${S.addons.map((a,i)=>`<tr><td>${esc(a.name)}</td><td><input type="number" value="${a.price}" data-change="adE" data-i="${i}" style="width:120px"></td><td class="small muted">per ${esc(a.per)}</td></tr>`).join('')}</tbody></table></div>`;
CH.plE=el=>{const p=S.plans[+el.dataset.i];p[el.dataset.k]=el.dataset.k==='name'?el.value:+el.value||0;audit('Edited plan '+p.name);save();toast('Saved')};
CH.plS=el=>{const p=S.plans[+el.dataset.i],s=el.dataset.s;p.services=el.checked?[...new Set([...p.services,s])]:p.services.filter(x=>x!==s);S.tenants.filter(t=>t.plan===p.id).forEach(t=>t.services=[...new Set([...p.services,...t.addons])]);audit(`Plan ${p.name}: ${el.checked?'added':'removed'} ${svcName(s)}`);render()};
CH.adE=el=>{S.addons[+el.dataset.i].price=+el.value||0;save();toast('Saved')};

VIEWS.audit=()=>head('Audit log','Every change made in the console, with who and when.')+`<div class="card"><div class="list">${S.audit.map(a=>`<div><span class="small muted" style="width:140px">${fdt(a.at)}</span><span class="sp small">${esc(a.text)}</span><span class="small muted">${esc(a.by)}</span></div>`).join('')||'<div class="empty">No activity yet.</div>'}</div><button class="btn bad" style="margin-top:14px" data-act="reset">Reset demo data</button></div>`;

/* ================= EVENTS ================= */
ACT.go=el=>{S.ui.view=el.dataset.v;render();scrollTo(0,0)};
ACT.tab=el=>{S.ui.tab[el.dataset.k]=el.dataset.v;render()};
ACT.closeModal=closeModal;
ACT.lfill=el=>{S.ui.login={id:el.dataset.id,phone:phoneOf(el.dataset.id)};render()};
ACT.lback=()=>{S.ui.login={};render()};
ACT.logout=()=>{S.ui.user=null;S.ui.login={};S.ui.view='overview';render()};
ACT.reset=()=>{try{localStorage.removeItem(KEY)}catch(e){}S=seed();render()};
document.addEventListener('click',ev=>{if(ev.target.id==='modal')return closeModal();const el=ev.target.closest('[data-act]');if(!el||!ACT[el.dataset.act])return;if(el.tagName==='A'&&el.dataset.act!=='support'&&!el.getAttribute('href').startsWith('#'))ev.preventDefault();ACT[el.dataset.act](el,ev)});
document.addEventListener('change',ev=>{const el=ev.target.closest('[data-change]');if(el&&CH[el.dataset.change])CH[el.dataset.change](el)});
document.addEventListener('keydown',ev=>{if(ev.key==='Escape')closeModal()});
document.addEventListener('submit',ev=>{const f=ev.target;
  if(f.id==='flog'){ev.preventDefault();const m=fv(f,'m').replace(/\D/g,'').slice(-10);const id=['super',...S.partners.filter(p=>p.active).map(p=>p.id)].find(i=>phoneOf(i)===m);if(!id)return toast('Not a Salon HR team number');S.ui.login={id,phone:m};render()}
  if(f.id==='fotp'){ev.preventDefault();if(fv(f,'o')!=='123456')return toast('Wrong OTP (demo: 123456)');S.ui.user=S.ui.login.id;S.ui.login={};S.ui.view='overview';audit('Logged in');render()}
  if(f.id==='fp'){ev.preventDefault();const n=fv(f,'n'),m=fv(f,'m').replace(/\D/g,'').slice(-10);if(!n||!/^[6-9]\d{9}$/.test(m))return toast('Name and valid mobile needed');S.partners.push({id:uid('p'),name:n,phone:m,email:fv(f,'e'),active:true,cap:+fv(f,'c')||10});audit('Added HR partner '+n);render();toast(n+' can now log in')}});

/* ================= V2: CONTACTS, CALLS, HEALTH, OPPORTUNITIES, DIRECTORY, TALENT, ANNOUNCEMENTS ================= */
const PN=['Ritu','Arjun','Kiran','Sonal','Vivek','Neeta','Farhan','Megha','Sunil','Pallavi','Rohit','Jaya'];
const SN=['Shah','Rao','Menon','Bhatt','Kapoor','Iyer','Qureshi','Ghosh','Pandey','Nair','Sethi','Mishra'];
function ensureV2(){if(S.v2)return;S.v2=1;S.calls=[];S.ann=[];
  S.tenants.forEach((t,i)=>{t.email=t.email||t.owner.split(' ')[0].toLowerCase()+'@'+t.salon.toLowerCase().replace(/[^a-z]/g,'').slice(0,12)+'.in';
    t.address=t.address||`Main Road, ${t.city}, ${t.state}`;t.branchList=t.branchList||Array.from({length:t.branches},(_,b)=>({name:b?`${t.city} branch ${b+1}`:`${t.city} main`,address:`Shop ${b+3}, Market Road, ${t.city}`}));
    t.mgrs=t.mgrs||Array.from({length:t.managers},(_,m)=>({name:PN[(i+m)%PN.length]+' '+SN[(i*3+m)%SN.length],phone:'98200'+String(10000+i*37+m*11).slice(-5),branch:t.branchList[(m+1)%t.branchList.length].name}));
    t.lastLogin=t.lastLogin||addDays(todayS,-[1,0,2,6,1,19,0,3,9,26,1][i%11])});
  const seedCalls=[['AURA01','Support','Helped set up wedding-season roster.',-3,''],['VELV03','Upsell','Pitched Performance & Incentives. Owner interested after Diwali.',-5,addDays(todayS,1)],['GROM10','Collection','Invoice overdue; owner says payment next week.',-6,addDays(todayS,0)],['SAFF04','Relationship','Monthly review call. Asked about ESI registration.',-2,addDays(todayS,3)]];
  seedCalls.forEach((c,i)=>{const t=T(c[0]);S.calls.push({id:uid('c'),tenant:c[0],by:t.partner?PT(t.partner).name:'Super Admin',type:c[1],note:c[2],at:addDays(todayS,c[3])+'T12:30:00',next:c[4],done:false})});
  S.cands=[['Anita Kale','Beautician',4,'Pune','Maharashtra',18000,'Immediate','Applied via website',-12],['Ramesh Yadav','Gents Hair Dresser (GHD)',6,'Mumbai','Maharashtra',22000,'15 days','Recruitment drive — Andheri',-20],['Shabnam Ali','Makeup Artist',3,'Mumbai','Maharashtra',24000,'Immediate','Ex-employee — opted in at exit',-9],['Joseph Thomas','Sr. Unisex Hair Dresser (Sr. UHD)',9,'Bengaluru','Karnataka',38000,'30 days','Applied via website',-4],['Lata Chauhan','Nail Artist',2,'Ahmedabad','Gujarat',16000,'Immediate','Academy referral (consented)',-15],['Harpreet Kaur','Beautician',5,'Delhi','Delhi',20000,'15 days','Applied via website',-7],['Mohit Saini','Unisex Hair Dresser (UHD)',4,'Jaipur','Rajasthan',21000,'Immediate','Ex-employee — opted in at exit',-25],['Revathi S','Spa Therapist',6,'Chennai','Tamil Nadu',19000,'30 days','Applied via website',-3],['Ayesha Siddiqui','Receptionist / Front Desk',2,'Lucknow','Uttar Pradesh',14000,'Immediate','Recruitment drive — Lucknow',-11],['Vinod Kumar','Helper',1,'Hyderabad','Telangana',11000,'Immediate','Applied via website',-1]]
   .map((c,i)=>({id:'C'+(301+i),name:c[0],role:c[1],exp:c[2],city:c[3],state:c[4],expect:c[5],notice:c[6],source:c[7],consentAt:addDays(todayS,c[8])+'T10:00:00',mobile:'97000'+String(20000+i*413).slice(-5),status:'Available',history:[]}));
  S.jobs=[{id:'J-501',tenant:'AURA01',role:'Sr. Unisex Hair Dresser (Sr. UHD)',count:2,city:'Mumbai',min:30000,max:40000,status:'Open',shortlist:[],at:addDays(todayS,-1)},{id:'J-502',tenant:'NAIL09',role:'Nail Artist',count:1,city:'Ahmedabad',min:15000,max:20000,status:'Open',shortlist:[],at:addDays(todayS,-4)},{id:'J-503',tenant:'URBN07',role:'Beautician',count:3,city:'Delhi',min:18000,max:24000,status:'Open',shortlist:[],at:addDays(todayS,-6)}];
  save()}
ensureV2();

/* health score */
function health(t){if(t.status==='Suspended')return[10,'At risk','c-bad',['Account suspended']];if(t.status==='Churned')return[0,'Churned','',[]];let s=100;const why=[];
  if(S.invoices.some(i=>i.tenant===t.id&&i.status==='Overdue')){s-=30;why.push('Overdue invoice')}
  const old=S.reqs.filter(r=>r.tenant===t.id&&r.status!=='Resolved'&&(Date.now()-new Date(r.at))/864e5>2).length;if(old){s-=15*old;why.push(old+' request(s) open > 48h')}
  const ll=(new Date(todayS)-new Date(t.lastLogin))/864e5;if(ll>14){s-=25;why.push('No owner login for '+Math.round(ll)+' days')}else if(ll>7){s-=10;why.push('Low recent usage')}
  if(!t.partner){s-=20;why.push('No HR partner')}
  const p=S.plans.find(x=>x.id===t.plan);if(t.staff>p.upto){s-=5;why.push('Over plan staff limit')}
  s=Math.max(0,s);return[s,s>=70?'Healthy':s>=40?'Watch':'At risk',s>=70?'c-ok':s>=40?'c-warn':'c-bad',why]}
/* upsell ideas */
function ideas(t){if(t.status!=='Active')return[];const p=S.plans.find(x=>x.id===t.plan),out=[];const ad=id=>S.addons.find(a=>a.id===id);
  if(t.staff>p.upto){const up=S.plans.find(x=>x.upto>=t.staff&&x.price>p.price);if(up)out.push(['plan',`Upgrade to ${up.name}`,`${t.staff} staff on a plan for up to ${p.upto}`,up.price-p.price])}
  if(!t.services.includes('compliance')&&t.staff>=8)out.push(['compliance','PF & ESI management',t.staff>=10?`${t.staff} staff — ESI is mandatory at 10+`:`${t.staff} staff — ESI becomes mandatory at 10`,ad('compliance').price*t.staff]);
  if(!t.services.includes('performance')&&t.staff>=6)out.push(['performance','Performance & incentives','Track targets vs salary for every stylist',ad('performance').price]);
  if(!t.services.includes('recruitment'))out.push(['recruitment','Recruitment & sourcing','Fill chairs from the talent pool',ad('recruitment').price]);
  if(!t.services.includes('bgv')&&t.staff>=10)out.push(['bgv','Background verification','Verify new joiners before they start',ad('bgv').price]);
  return out}
const telL=ph=>`<a class="btn s" href="tel:+91${esc(ph)}">Call</a>`;const waL=ph=>`<a class="btn s" href="https://wa.me/91${esc(ph)}" target="_blank" rel="noopener">WhatsApp</a>`;const mailL=e=>e?`<a class="btn s" href="mailto:${esc(e)}">Email</a>`:'';
const contactRow=(name,role,ph,email,extra)=>`<tr><td><b>${esc(name)}</b><br><span class="small muted">${esc(role)}${extra?' · '+esc(extra):''}</span></td><td class="small">+91 ${esc(ph)}${email?'<br>'+esc(email):''}</td><td><span class="row" style="gap:4px">${telL(ph)}${waL(ph)}${mailL(email)}</span></td></tr>`;

/* --- salon modal: new tabs --- */
function contactsTab(t){return`<p class="sub" style="margin-bottom:8px">Call, WhatsApp or email directly. Log every conversation in Call log so the next person knows what happened.</p><table class="stack"><thead><tr><th>Person</th><th>Contact</th><th></th></tr></thead><tbody>${contactRow(t.owner,'Owner',t.ownerPhone,t.email)}${(t.mgrs||[]).map(m=>contactRow(m.name,'Manager',m.phone,'',m.branch)).join('')}</tbody></table>
  <h3 style="margin-top:16px">Branches</h3><div class="list">${(t.branchList||[]).map(b=>`<div><span class="sp"><b>${esc(b.name)}</b><br><span class="small muted">${esc(b.address)}</span></span></div>`).join('')}</div>
  <div class="list" style="margin-top:10px"><div><span class="sp">Registered address</span><span class="small">${esc(t.address)}</span></div><div><span class="sp">Last owner login</span><span class="small">${fdate(t.lastLogin)}</span></div></div>`}
function callsTab(t){const cs=S.calls.filter(c=>c.tenant===t.id).sort((a,b)=>a.at<b.at?1:-1);return`<form id="fcall" data-t="${t.id}" class="fg"><label class="f">Type<select name="ty">${['Support','Upsell','Collection','Onboarding','Relationship'].map(x=>`<option>${x}</option>`).join('')}</select></label><label class="f">Follow-up date<input type="date" name="nx"></label><label class="f" style="grid-column:1/-1">What was discussed / outcome<textarea name="n" required></textarea></label><div><button class="btn p">Log call</button></div></form>
  <div class="list" style="margin-top:14px">${cs.map(c=>`<div style="align-items:flex-start"><span class="small muted" style="width:110px">${fdt(c.at)}</span><span class="sp small">${chip(c.type,c.type==='Upsell'?'c-b':c.type==='Collection'?'c-bad':'c-info')} ${esc(c.note)}${c.next?`<br><span class="muted">Follow-up ${fdate(c.next)}${c.done?' · done':''}</span>`:''}</span><span class="small muted">${esc(c.by)}</span></div>`).join('')||'<div class="empty">No calls logged yet.</div>'}</div>`}
function oppTab(t){const L=ideas(t);return L.length?`<table class="stack"><thead><tr><th>Opportunity</th><th>Why</th><th class="n">Est. monthly</th><th></th></tr></thead><tbody>${L.map(o=>`<tr><td><b>${esc(o[1])}</b></td><td class="small">${esc(o[2])}</td><td class="n">${inr(o[3])}</td><td><button class="btn s" data-act="pitch" data-t="${t.id}" data-o="${esc(o[1])}">Log pitch</button></td></tr>`).join('')}</tbody></table>`:'<div class="empty">No obvious opportunities right now.</div>'}
function healthTab(t){const h=health(t);return`<div class="kpi" style="max-width:260px"><b>${h[0]}/100</b><span>${chip(h[1],h[2])}</span></div><h3 style="margin-top:14px">What affects it</h3><ul>${h[3].map(x=>`<li>${esc(x)}</li>`).join('')||'<li>Everything looks good.</li>'}</ul><p class="small muted">Score drops for overdue invoices, requests open past 48 hours, low owner logins, no HR partner and plan overuse.</p>`}

/* patch the salon modal to add new tabs */
const EXTRA={contact:['Contacts',contactsTab],calls:['Call log',callsTab],opp:['Opportunities',oppTab],health:['Health',healthTab]};
const _tenModal=tenModal;
tenModal=function(id,tab){const t=T(id);const k=tab||S.ui.tab.ten||'contact';
  if(!EXTRA[k]){_tenModal(id,k);addTabs(id,k);return}
  _tenModal(id,'ov');S.ui.tab.ten=k;const tb=document.querySelector('#mbody .tabs');tb.querySelectorAll('button').forEach(b=>b.classList.remove('on'));addTabs(id,k);
  tb.nextElementSibling.innerHTML=EXTRA[k][1](t);bindCall()};
function addTabs(id,k){const tb=document.querySelector('#mbody .tabs');if(!tb)return;if(!tb.querySelector('[data-v="contact"]'))Object.entries(EXTRA).reverse().forEach(([kk,v])=>{const b=document.createElement('button');b.dataset.v=kk;b.textContent=v[0];tb.prepend(b)});
  tb.querySelectorAll('button').forEach(b=>{b.classList.toggle('on',b.dataset.v===k);b.onclick=()=>tenModal(id,b.dataset.v)})}
function bindCall(){const f=$('#fcall');if(!f)return;f.onsubmit=ev=>{ev.preventDefault();const n=fv(f,'n');if(!n)return toast('Write what was discussed');S.calls.push({id:uid('c'),tenant:f.dataset.t,by:me().name,type:fv(f,'ty'),note:n,at:new Date().toISOString(),next:fv(f,'nx'),done:false});
  audit(`Logged ${fv(f,'ty').toLowerCase()} call with ${T(f.dataset.t).salon}`);render();tenModal(f.dataset.t,'calls');toast('Call logged')}}
ACT.pitch=el=>{S.ui.tab.ten='calls';tenModal(el.dataset.t,'calls');const f=$('#fcall');f.ty.value='Upsell';f.n.value='Pitched '+el.dataset.o+': ';f.n.focus()};
ACT.fuDone=el=>{const c=S.calls.find(x=>x.id===el.dataset.id);c.done=true;audit('Follow-up done: '+T(c.tenant).salon);render()};

/* --- overview additions: follow-ups & at-risk --- */
const _ov=VIEWS.overview;VIEWS.overview=()=>{const ts=myT();const fu=S.calls.filter(c=>c.next&&!c.done&&c.next<=addDays(todayS,2)&&ts.some(t=>t.id===c.tenant)).sort((a,b)=>a.next<b.next?-1:1);
  const risk=ts.map(t=>[t,health(t)]).filter(x=>x[1][0]<70&&x[0].status!=='Churned').sort((a,b)=>a[1][0]-b[1][0]);
  return _ov()+`<div class="grid g2"><div class="card"><h2>Follow-ups due</h2>${fu.length?`<div class="list">${fu.map(c=>{const t=T(c.tenant);return`<div><span class="sp"><b>${esc(t.salon)}</b> ${chip(c.type)}<br><span class="small muted">${esc(c.note)}</span></span>${chip(fdate(c.next),c.next<todayS?'c-bad':'c-warn')}<span class="row" style="gap:4px">${telL(t.ownerPhone)}<button class="btn s ok" data-act="fuDone" data-id="${c.id}">Done</button></span></div>`}).join('')}</div>`:'<div class="empty">No follow-ups due.</div>'}</div>
  <div class="card"><h2>Salons needing attention</h2>${risk.length?`<div class="list">${risk.map(([t,h])=>`<div class="click" data-act="ten" data-id="${t.id}" style="cursor:pointer"><span class="sp"><b>${esc(t.salon)}</b><br><span class="small muted">${esc(h[3].join(' · '))}</span></span>${chip(h[0]+' · '+h[1],h[2])}</div>`).join('')}</div>`:'<div class="empty">All salons healthy.</div>'}</div></div>`};

/* --- salons list: health column --- */
const _sal=VIEWS.salons;VIEWS.salons=()=>{let h=_sal();myT().forEach(t=>{const x=health(t);h=h.replace(`${chip(t.status,TSTC[t.status])}</td></tr>`,`${chip(t.status,TSTC[t.status])}<br>${chip('Health '+x[0],x[2])}</td></tr>`)});return h};

/* --- opportunities --- */
VIEWS.opps=()=>{const rows=myT().flatMap(t=>ideas(t).map(o=>({t,o}))).sort((a,b)=>b.o[3]-a.o[3]);const tot=rows.reduce((a,r)=>a+r.o[3],0);
  return head('Opportunities',`Services your salons don't have yet but clearly need · ${inr(tot)}/month potential`)+`<div class="card"><table class="stack"><thead><tr><th>Salon</th><th>Opportunity</th><th>Why</th><th class="n">Est. monthly</th><th>Owner</th><th></th></tr></thead><tbody>${rows.map(({t,o})=>`<tr><td><b>${esc(t.salon)}</b><br><span class="small muted">${t.id} · ${t.partner?esc(PT(t.partner).name):'No partner'}</span></td><td>${esc(o[1])}</td><td class="small">${esc(o[2])}</td><td class="n">${inr(o[3])}</td><td class="small">${esc(t.owner)}<br>+91 ${t.ownerPhone}</td><td><span class="row" style="gap:4px">${telL(t.ownerPhone)}<button class="btn s" data-act="pitch" data-t="${t.id}" data-o="${esc(o[1])}">Log pitch</button></span></td></tr>`).join('')||'<tr><td colspan="6" class="muted">No opportunities.</td></tr>'}</tbody></table></div>`};

/* --- directory: owners & managers only (business contacts) --- */
VIEWS.directory=()=>{const q=(S.ui.tab.dq||'').toLowerCase();const ppl=S.tenants.flatMap(t=>[{t,name:t.owner,role:'Owner',ph:t.ownerPhone,email:t.email,br:'All branches'},...(t.mgrs||[]).map(m=>({t,name:m.name,role:'Manager',ph:m.phone,email:'',br:m.branch}))]).filter(p=>!q||(p.name+' '+p.t.salon+' '+p.t.city+' '+p.ph).toLowerCase().includes(q));
  return head('Directory','Owners and managers of every client salon — your business contacts.')+`<div class="note i" style="margin-bottom:14px">Salon staff records stay inside each salon's own HRMS and are used only to run that salon's HR. They are not listed here or used for recruitment.</div>
  <div class="card"><input type="search" placeholder="Search name, salon, city or mobile" value="${esc(S.ui.tab.dq||'')}" data-change="dq" style="max-width:340px;margin-bottom:10px"><table class="stack"><thead><tr><th>Person</th><th>Salon</th><th>Contact</th><th></th></tr></thead><tbody>${ppl.map(p=>`<tr><td><b>${esc(p.name)}</b><br><span class="small muted">${p.role} · ${esc(p.br)}</span></td><td>${esc(p.t.salon)}<br><span class="small muted">${p.t.id} · ${esc(p.t.city)}</span></td><td class="small">+91 ${esc(p.ph)}${p.email?'<br>'+esc(p.email):''}</td><td><span class="row" style="gap:4px">${telL(p.ph)}${waL(p.ph)}${mailL(p.email)}</span></td></tr>`).join('')}</tbody></table></div>`};
CH.dq=el=>{S.ui.tab.dq=el.value;render()};

/* --- talent pool (consent-based) --- */
VIEWS.talent=()=>{const q=(S.ui.tab.tq2||'').toLowerCase(),rf=S.ui.tab.tr||'';const L=S.cands.filter(c=>(!rf||c.role===rf)&&(!q||(c.name+' '+c.city+' '+c.role).toLowerCase().includes(q)));
  return head('Talent pool','Candidates who chose to be considered for salon jobs through Salon HR.',`<button class="btn p" data-act="addC">Add candidate</button>`)+
  `<div class="note i" style="margin-bottom:14px">Everyone here gave consent: direct applicants, recruitment-drive candidates and former employees who opted in at exit. Each record shows when consent was given. Candidates can ask to be removed at any time.</div>
  <div class="card"><div class="row" style="margin-bottom:10px"><select data-change="tr" style="width:auto"><option value="">All roles</option>${[...new Set(S.cands.map(c=>c.role))].map(r=>`<option${r===rf?' selected':''}>${esc(r)}</option>`).join('')}</select><input type="search" placeholder="Search name, city or role" value="${esc(S.ui.tab.tq2||'')}" data-change="tq2" style="max-width:300px"></div>
  <table class="stack"><thead><tr><th>Candidate</th><th>Role</th><th>City</th><th class="n">Expects</th><th>Source & consent</th><th>Status</th><th></th></tr></thead><tbody>${L.map(c=>`<tr><td><b>${esc(c.name)}</b><br><span class="small muted">${c.exp} yrs · notice ${esc(c.notice)}</span></td><td>${esc(c.role)}</td><td>${esc(c.city)}</td><td class="n">${inr(c.expect)}</td><td class="small">${esc(c.source)}<br><span class="muted">Consent ${fdate(c.consentAt)}</span></td><td>${chip(c.status,c.status==='Available'?'c-ok':c.status==='Placed'?'c-info':'c-warn')}</td><td><span class="row" style="gap:4px">${telL(c.mobile)}<button class="btn s bad" data-act="rmC" data-id="${c.id}">Remove</button></span></td></tr>`).join('')}</tbody></table></div>`};
CH.tr=el=>{S.ui.tab.tr=el.value;render()};CH.tq2=el=>{S.ui.tab.tq2=el.value;render()};
ACT.rmC=el=>{const c=S.cands.find(x=>x.id===el.dataset.id);S.cands=S.cands.filter(x=>x.id!==c.id);S.jobs.forEach(j=>j.shortlist=j.shortlist.filter(x=>x!==c.id));audit('Removed candidate '+c.name+' from talent pool');render()};
ACT.addC=()=>openModal(`<h2>Add candidate</h2><form id="fc" class="fg"><label class="f">Name *<input name="n"></label><label class="f">Mobile *<input name="m" inputmode="tel"></label><label class="f">Role *<input name="r" list="dlR"></label><datalist id="dlR">${DESIGNATIONS.map(d=>`<option value="${esc(d)}">`).join('')}</datalist><label class="f">Experience (years)<input type="number" name="x" value="1"></label><label class="f">City *<input name="c"></label><label class="f">Expected salary (₹)<input type="number" name="s"></label><label class="f">Notice<select name="nt"><option>Immediate</option><option>15 days</option><option>30 days</option></select></label><label class="f">Source<select name="src"><option>Applied via website</option><option>Recruitment drive</option><option>Academy referral (consented)</option><option>Walk-in</option></select></label>
  <label class="chk" style="grid-column:1/-1"><input type="checkbox" name="ok"> The candidate has agreed to be contacted about salon jobs and to have their details shared with hiring salons.</label><div><button class="btn p">Add to pool</button></div></form>`,()=>{$('#fc').onsubmit=ev=>{ev.preventDefault();const f=$('#fc');if(!fv(f,'ok'))return toast('Candidate consent is required');if(!fv(f,'n')||!fv(f,'m')||!fv(f,'r')||!fv(f,'c'))return toast('Name, mobile, role and city are required');
  S.cands.unshift({id:'C'+(301+S.cands.length),name:fv(f,'n'),mobile:fv(f,'m').replace(/\D/g,'').slice(-10),role:fv(f,'r'),exp:+fv(f,'x')||0,city:fv(f,'c'),state:'',expect:+fv(f,'s')||0,notice:fv(f,'nt'),source:fv(f,'src'),consentAt:new Date().toISOString(),status:'Available',history:[]});audit('Added candidate '+fv(f,'n'));closeModal();render()}});
const DESIGNATIONS=['Helper','Gents Hair Dresser (GHD)','Sr. Gents Hair Dresser (Sr. GHD)','Unisex Hair Dresser (UHD)','Sr. Unisex Hair Dresser (Sr. UHD)','Hair Colourist','Beautician','Sr. Beautician','Nail Artist','Makeup Artist','Spa Therapist','Receptionist / Front Desk','Salon Floor Manager','Asst. Salon Manager','Salon Manager'];

/* --- job openings (for salons that use Recruitment & Sourcing) --- */
VIEWS.jobs=()=>{const js=S.jobs.filter(j=>myT().some(t=>t.id===j.tenant));
  return head('Job openings','Open positions from salons using Recruitment & Sourcing. Shortlist from the talent pool and share profiles with the salon.',`<button class="btn p" data-act="addJ">Add opening</button>`)+
  js.map(j=>{const t=T(j.tenant);const match=S.cands.filter(c=>c.status==='Available'&&c.role===j.role&&c.city===j.city&&!j.shortlist.includes(c.id));const sl=j.shortlist.map(id=>S.cands.find(c=>c.id===id)).filter(Boolean);
   return`<div class="card"><div class="row"><div class="sp"><h2 style="font-size:19px">${esc(j.role)} × ${j.count}</h2><div class="sub">${esc(t.salon)} · ${esc(j.city)} · ${inr(j.min)}–${inr(j.max)} · ${j.id} · opened ${fdate(j.at)}</div></div>${chip(j.status,j.status==='Open'?'c-warn':'c-ok')}</div>
   <h3 style="margin-top:12px">Shortlist (${sl.length})</h3>${sl.length?`<table class="stack"><tbody>${sl.map(c=>`<tr><td><b>${esc(c.name)}</b><br><span class="small muted">${c.exp} yrs · ${inr(c.expect)} · notice ${esc(c.notice)}</span></td><td>${chip(c.status)}</td><td><span class="row" style="gap:4px">${telL(c.mobile)}${c.status!=='Placed'?`<button class="btn s ok" data-act="place" data-j="${j.id}" data-c="${c.id}">Mark placed</button>`:''}</span></td></tr>`).join('')}</tbody></table>`:'<p class="small muted">No one shortlisted yet.</p>'}
   <h3 style="margin-top:12px">Matching candidates in the pool (${match.length})</h3>${match.length?`<div class="list">${match.map(c=>`<div><span class="sp"><b>${esc(c.name)}</b> · ${c.exp} yrs · expects ${inr(c.expect)}<br><span class="small muted">${esc(c.source)}</span></span><button class="btn s" data-act="short" data-j="${j.id}" data-c="${c.id}">Shortlist</button></div>`).join('')}</div>`:'<p class="small muted">No available candidates match this role and city yet.</p>'}</div>`}).join('')||'<div class="card"><div class="empty">No open positions.</div></div>'};
ACT.short=el=>{const j=S.jobs.find(x=>x.id===el.dataset.j),c=S.cands.find(x=>x.id===el.dataset.c);j.shortlist.push(c.id);c.status='Interviewing';audit(`Shortlisted ${c.name} for ${T(j.tenant).salon} (${j.role})`);render()};
ACT.place=el=>{const j=S.jobs.find(x=>x.id===el.dataset.j),c=S.cands.find(x=>x.id===el.dataset.c);c.status='Placed';j.placed=(j.placed||0)+1;if(j.placed>=j.count)j.status='Filled';audit(`Placed ${c.name} at ${T(j.tenant).salon} — recruitment fee to invoice`);render();toast('Placed — add the recruitment fee to the salon\'s next invoice')};
ACT.addJ=()=>openModal(`<h2>Add job opening</h2><form id="fj" class="fg"><label class="f">Salon<select name="t">${myT().filter(t=>t.status==='Active').map(t=>`<option value="${t.id}">${esc(t.salon)}</option>`).join('')}</select></label><label class="f">Role<select name="r">${DESIGNATIONS.map(d=>`<option>${esc(d)}</option>`).join('')}</select></label><label class="f">Positions<input type="number" name="n" value="1" min="1"></label><label class="f">City<input name="c"></label><label class="f">Salary from (₹)<input type="number" name="a"></label><label class="f">Salary to (₹)<input type="number" name="b"></label><div><button class="btn p">Add</button></div></form>`,()=>{$('#fj').onsubmit=ev=>{ev.preventDefault();const f=$('#fj'),t=T(fv(f,'t'));S.jobs.unshift({id:'J-'+(501+S.jobs.length),tenant:t.id,role:fv(f,'r'),count:+fv(f,'n')||1,city:fv(f,'c')||t.city,min:+fv(f,'a')||0,max:+fv(f,'b')||0,status:'Open',shortlist:[],at:todayS});audit('Added opening for '+t.salon);closeModal();render()}});

/* --- announcements --- */
VIEWS.ann=()=>head('Announcements','Send updates to salon owners — law changes, new features, holiday schedules. Delivered in their portal and on WhatsApp.')+
  `<div class="card"><form id="fann" class="fg"><label class="f">Title *<input name="t" placeholder="ESI wage ceiling update"></label><label class="f">Send to<select name="a"><option value="all">All active salons</option>${S.plans.map(p=>`<option value="plan:${p.id}">${esc(p.name)} plan salons</option>`).join('')}${[...new Set(S.tenants.map(t=>t.state))].map(s=>`<option value="state:${esc(s)}">Salons in ${esc(s)}</option>`).join('')}</select></label><label class="f" style="grid-column:1/-1">Message *<textarea name="m"></textarea></label><div><button class="btn p">Send announcement</button></div></form></div>
  <div class="card"><h2>Sent</h2><div class="list">${S.ann.map(a=>`<div style="align-items:flex-start"><span class="small muted" style="width:120px">${fdt(a.at)}</span><span class="sp"><b>${esc(a.t)}</b><br><span class="small">${esc(a.m)}</span></span><span class="small muted">${a.n} salons</span></div>`).join('')||'<div class="empty">Nothing sent yet.</div>'}</div></div>`;

/* --- partners: performance --- */
const _par=VIEWS.partners;VIEWS.partners=()=>{const mStart=curMK+'-01';return _par()+`<div class="card"><h2>Partner performance · ${mname(curMK)}</h2><table class="stack"><thead><tr><th>Partner</th><th class="n">Calls logged</th><th class="n">Upsell pitches</th><th class="n">Requests resolved</th><th class="n">Compliance tasks done</th><th class="n">Avg salon health</th></tr></thead><tbody>${S.partners.map(p=>{const ts=S.tenants.filter(t=>t.partner===p.id),cs=S.calls.filter(c=>c.by===p.name&&c.at>=mStart);const h=ts.length?Math.round(ts.reduce((a,t)=>a+health(t)[0],0)/ts.length):0;
  return`<tr><td><b>${esc(p.name)}</b></td><td class="n">${cs.length}</td><td class="n">${cs.filter(c=>c.type==='Upsell').length}</td><td class="n">${S.reqs.filter(r=>r.status==='Resolved'&&ts.some(t=>t.id===r.tenant)).length}</td><td class="n">${S.comp.filter(c=>c.by===p.name).length}</td><td class="n">${h?chip(h,h>=70?'c-ok':h>=40?'c-warn':'c-bad'):'—'}</td></tr>`}).join('')}</tbody></table></div>`};

document.addEventListener('submit',ev=>{const f=ev.target;if(f.id!=='fann')return;ev.preventDefault();const t=fv(f,'t'),m=fv(f,'m'),a=fv(f,'a');if(!t||!m)return toast('Title and message needed');
  const n=S.tenants.filter(x=>x.status==='Active'&&(a==='all'||(a.startsWith('plan:')&&x.plan===a.slice(5))||(a.startsWith('state:')&&x.state===a.slice(6)))).length;S.ann.unshift({t,m,a,n,at:new Date().toISOString()});audit(`Announcement "${t}" sent to ${n} salons`);render();toast('Sent to '+n+' salons')});


/* ================= VERIFIED WORK HISTORY REGISTRY ================= */
function ensureV3(){if(S.v3)return;S.v3=1;const nowL=()=>todayS+'T12:00:00';
  const P=[['Priya Sharma','9000000000','1996-01-10','4321','ABCDE1234F',[['AURA01','Sr. Unisex Hair Dresser (Sr. UHD)','2024-03-11','','Present'],['ext:Lakme-style salon, Mumbai','Unisex Hair Dresser (UHD)','2021-06-01','2024-02-28','Resigned']],'2024-03-11'],
   ['Rahul Verma','9001234567','1997-02-11','4322','ABCDE1235F',[['AURA01','Gents Hair Dresser (GHD)','2025-01-06','','Present']],'2025-01-06'],
   ['Joseph Thomas','9711100001','1990-05-02','7781','BQXPT4411K',[['VELV03','Sr. Unisex Hair Dresser (Sr. UHD)','2023-02-01','2025-09-30','Resigned'],['TRES05','Unisex Hair Dresser (UHD)','2020-04-01','2023-01-15','Resigned']],'2023-02-01'],
   ['Harpreet Kaur','9711100002','1995-08-19','2290','CKLPK9921M',[['URBN07','Beautician','2022-07-01','2026-06-30','Resigned']],'2022-07-01'],
   ['Mohit Saini','9711100003','1998-11-03','6612','DNSPS7740Q',[['SAFF04','Unisex Hair Dresser (UHD)','2024-01-10','2026-08-31','Terminated after show-cause']],'2024-01-10'],
   ['Lata Chauhan','9711100004','2000-03-27','1180','EQLPC1209R',[['NAIL09','Nail Artist','2026-11-24','','Present']],'2026-11-24'],
   ['Sana Qureshi','9711100005','1993-12-12','5543','FRZPQ5531T',[['BLOM06','Makeup Artist','2021-03-01','','Present']],'2021-03-01'],
   ['Deepa Rao','9007407402','1993-07-16','3320','GHTPR6620P',[['AURA01','Beautician','2025-02-10','2026-10-02','Resigned']],'2025-02-10']];
  S.vwh=P.map((p,i)=>({id:'W'+(7001+i),name:p[0],mobile:p[1],dob:p[2],aadhaar4:p[3],pan:p[4],consentAt:p[6]+'T12:00:00',confirmedAt:p[6]+'T12:00:00',status:'Active',
    jobs:p[5].map(j=>({salon:j[0],role:j[1],from:j[2],to:j[3],exit:j[4],verified:j[0].startsWith('ext:')?'Reference call':'Salon HR payroll records'})),
    checks:[{type:'Identity (Aadhaar/PAN)',result:'Clear',at:p[6]},{type:'Address',result:i%3?'Clear':'Pending',at:p[6]}],log:[{at:p[6]+'T12:00:00',text:'Consent given in staff app joining form'}],shares:[]}));
  S.vwh.push({id:'W7009',name:'(deleted)',status:'Withdrawn',consentAt:'2025-04-02T12:00:00',withdrawnAt:addDays(todayS,-20)+'T10:00:00',jobs:[],checks:[],shares:[],log:[{at:'2025-04-02T12:00:00',text:'Consent given'},{at:addDays(todayS,-20)+'T10:00:00',text:'Consent withdrawn in staff app — personal details and work history deleted'},{at:'2025-06-10T12:00:00',text:'Earlier: 1 verification shared with a client salon (with approval)'}]});
  save()}
ensureV3();
const salonLabel=s=>s.startsWith('ext:')?s.slice(4)+' (outside Salon HR)':(T(s)?T(s).salon+', '+T(s).city:s);
const yearDue=w=>w.status==='Active'&&(new Date(todayS)-new Date(w.confirmedAt.slice(0,10)))/864e5>=365;
VIEWS.vwh=()=>{const q=(S.ui.tab.wq||'').toLowerCase();const L=S.vwh.filter(w=>!q||(w.name+' '+(w.mobile||'')+' '+(w.pan||'')).toLowerCase().includes(q));const act=S.vwh.filter(w=>w.status==='Active');
  return head('Verified work history','Employees who opted in to keep their verified work history with Salon HR. Shared with a new employer only after the employee approves each time.')+
  `<div class="grid g4" style="margin-bottom:14px"><div class="kpi"><b>${act.length}</b><span>Active records</span></div><div class="kpi"><b>${act.reduce((a,w)=>a+w.jobs.length,0)}</b><span>Verified employments</span></div><div class="kpi"><b>${S.vwh.reduce((a,w)=>a+w.shares.filter(s=>s.status==='approved').length,0)}</b><span>Shares approved for BGV</span></div><div class="kpi"><b>${act.filter(yearDue).length}</b><span>Yearly checks due</span></div></div>
  <div class="note i" style="margin-bottom:14px">Records stay with no end date while consent is active. If an employee withdraws, personal details and history are deleted and only the consent log is kept as proof. Only facts are recorded — no opinions or "do not hire" remarks. Salary, bank, documents, family and health details are never stored here.</div>
  <div class="card"><input type="search" placeholder="Search name, mobile or PAN" value="${esc(S.ui.tab.wq||'')}" data-change="wq" style="max-width:320px;margin-bottom:10px"><table class="stack"><thead><tr><th>Person</th><th>Current / last salon</th><th class="n">Employments</th><th>Consent</th><th>Status</th></tr></thead><tbody>${L.map(w=>{const last=w.jobs[0];return`<tr class="click" data-act="vwhOpen" data-id="${w.id}"><td><b>${esc(w.name)}</b><br><span class="small muted">${w.id}${w.mobile?' · +91 '+w.mobile:''}</span></td><td class="small">${last?esc(salonLabel(last.salon))+'<br><span class="muted">'+esc(last.role)+'</span>':'—'}</td><td class="n">${w.jobs.length}</td><td class="small">${fdate(w.consentAt)}${w.withdrawnAt?'<br>Withdrawn '+fdate(w.withdrawnAt):''}</td><td>${chip(w.status,w.status==='Active'?'c-ok':'')}${yearDue(w)?' '+chip('Yearly check due','c-warn'):''}</td></tr>`}).join('')}</tbody></table></div>`};
CH.wq=el=>{S.ui.tab.wq=el.value;render()};
ACT.vwhOpen=el=>vwhModal(el.dataset.id);
function vwhModal(id){const w=S.vwh.find(x=>x.id===id);
  if(w.status!=='Active')return openModal(`<h2>${w.id} — withdrawn</h2><p class="sub">Personal details and work history were deleted on ${fdate(w.withdrawnAt)}. Only this proof log remains.</p><div class="list">${w.log.map(l=>`<div><span class="small muted" style="width:120px">${fdate(l.at)}</span><span class="sp small">${esc(l.text)}</span></div>`).join('')}</div>`);
  openModal(`<h2>${esc(w.name)}</h2><p class="sub">${w.id} · consent ${fdate(w.consentAt)} · last confirmed ${fdate(w.confirmedAt)} ${yearDue(w)?chip('Yearly check due','c-warn'):''}</p>
  <table style="margin-top:6px"><tbody>${[['Mobile','+91 '+w.mobile],['Date of birth',fdate(w.dob)],['Aadhaar','XXXX XXXX '+w.aadhaar4],['PAN',w.pan.slice(0,2)+'XXX'+w.pan.slice(5)]].map(r=>`<tr><td class="muted" style="width:35%">${r[0]}</td><td>${esc(r[1])}</td></tr>`).join('')}</tbody></table>
  <h3 style="margin-top:14px">Employment history</h3><table class="stack"><thead><tr><th>Salon</th><th>Role</th><th>Period</th><th>Exit</th><th>Verified by</th></tr></thead><tbody>${w.jobs.map(j=>`<tr><td>${esc(salonLabel(j.salon))}</td><td>${esc(j.role)}</td><td class="small">${fdate(j.from)} – ${j.to?fdate(j.to):'Present'}</td><td class="small">${esc(j.exit)}</td><td class="small">${esc(j.verified)}</td></tr>`).join('')}</tbody></table>
  <h3 style="margin-top:14px">Checks on file</h3><div class="list">${w.checks.map(c=>`<div><span class="sp">${esc(c.type)}</span>${chip(c.result,c.result==='Clear'?'c-ok':'c-warn')}<span class="small muted">${fdate(c.at)}</span></div>`).join('')}</div>
  <h3 style="margin-top:14px">Use for a new BGV</h3><p class="small muted">A client salon is verifying this person. The employee gets a request in their staff app and must approve before anything is shared.</p>
  <form id="fsh" class="row" style="margin-top:8px"><select name="t" style="width:auto">${S.tenants.filter(t=>t.status==='Active').map(t=>`<option value="${t.id}">${esc(t.salon)}, ${esc(t.city)}</option>`).join('')}</select><button class="btn p">Request employee approval</button></form>
  ${w.shares.length?`<div class="list" style="margin-top:10px">${w.shares.map(s=>`<div><span class="sp">${esc(salonLabel(s.to))}<br><span class="small muted">Requested ${fdate(s.at)}</span></span>${chip(s.status==='approved'?'Approved — reused: identity, address, '+w.jobs.length+' employment(s)':s.status==='pending'?'Waiting for employee':'Declined',s.status==='approved'?'c-ok':s.status==='pending'?'c-warn':'c-bad')}${s.status==='pending'?`<button class="btn s" data-act="vwhDemoOk" data-w="${w.id}" data-s="${s.id}">Demo: employee approves</button>`:''}</div>`).join('')}</div>`:''}
  <h3 style="margin-top:14px">Consent log</h3><div class="list">${w.log.map(l=>`<div><span class="small muted" style="width:120px">${fdate(l.at)}</span><span class="sp small">${esc(l.text)}</span></div>`).join('')}</div>
  <div class="row" style="margin-top:14px">${yearDue(w)?`<button class="btn" data-act="vwhRemind" data-id="${w.id}">Send yearly check</button>`:''}<span class="sp"></span><button class="btn bad" data-act="vwhWithdraw" data-id="${w.id}">Record withdrawal</button></div>`,()=>{
  $('#fsh').onsubmit=ev=>{ev.preventDefault();const t=fv($('#fsh'),'t');const sid=uid('s');w.shares.unshift({id:sid,to:t,at:todayS+'T12:00:00',status:'pending'});if(PLATFORM.apps.hrms&&PLATFORM.apps.hrms.findByMobile(w.mobile))PLATFORM.emit('vwhShare',{mobile:w.mobile,to:T(t).salon+', '+T(t).city,why:'They are running your background verification',ref:sid});w.log.push({at:todayS+'T12:00:00',text:`Share requested for BGV by ${T(t).salon}`});audit(`Requested ${w.name}'s approval to share work history with ${T(t).salon}`);vwhModal(w.id);toast('Request sent to the employee\'s staff app')}})}
ACT.vwhDemoOk=el=>{const w=S.vwh.find(x=>x.id===el.dataset.w),s=w.shares.find(x=>x.id===el.dataset.s);s.status='approved';w.log.push({at:todayS+'T12:00:00',text:`Employee approved sharing with ${salonLabel(s.to)}`});audit(`${w.name} approved sharing with ${salonLabel(s.to)} — BGV checks reused`);vwhModal(w.id);toast('Approved — matching checks reused in the BGV report')};
ACT.vwhRemind=el=>{const w=S.vwh.find(x=>x.id===el.dataset.id);w.log.push({at:todayS+'T12:00:00',text:'Yearly check sent to staff app'});w.confirmedAt=todayS+'T12:00:00';audit('Yearly check sent to '+w.name);vwhModal(w.id);toast('Yearly check sent')};
ACT.vwhWithdraw=el=>{const w=S.vwh.find(x=>x.id===el.dataset.id);openModal(`<h2>Record withdrawal for ${esc(w.name)}?</h2><p class="sub">Use this when the employee withdraws by email or phone. Personal details and history are deleted now; only the consent log stays as proof.</p><div class="row" style="margin-top:12px"><span class="sp"></span><button class="btn bad" data-act="vwhWithdrawGo" data-id="${w.id}">Delete record</button></div>`)};
ACT.vwhWithdrawGo=el=>{const w=S.vwh.find(x=>x.id===el.dataset.id);const n=w.jobs.length,sh=w.shares.filter(s=>s.status==='approved').length;const keep={id:w.id,name:'(deleted)',status:'Withdrawn',consentAt:w.consentAt,withdrawnAt:todayS+'T12:00:00',jobs:[],checks:[],shares:[],log:[...w.log.map(l=>({at:l.at,text:l.text.replace(/ by .*| with .*/,'')})),{at:todayS+'T12:00:00',text:`Consent withdrawn — personal details and ${n} employment record(s) deleted; ${sh} past share(s) logged`}]};
  Object.keys(w).forEach(k=>delete w[k]);Object.assign(w,keep);audit('Verified work history '+keep.id+' withdrawn and deleted');closeModal();render();toast('Record deleted; proof log kept')};


/* ================= PLATFORM INTEGRATION (console) ================= */
function syncHRMS(){const h=PLATFORM.apps.hrms,t=T('AURA01');if(!h||!h.stats||!t)return;const st=h.stats();t.staff=st.staff;t.branches=st.branches;t.branchList=st.branchList;t.mgrs=st.managers;t.managers=st.managers.length;save()}
PLATFORM.apps.console={show(){closeModal();syncHRMS();render();document.title='Salon HR — Console';scrollTo(0,0)},
  tenant(id){const t=T(id);if(!t)return null;const p=t.partner?PT(t.partner):null;return{plan:S.plans.find(x=>x.id===t.plan),services:t.services.slice(),partner:p?{name:p.name,phone:p.phone,email:p.email}:null,reqs:S.reqs.filter(r=>r.tenant===id).map(r=>Object.assign({},r)),svcAll:SVC}}};
PLATFORM.on('lead',d=>{S.leads.unshift({id:'L'+(101+S.leads.length),salon:d.salon||'(call-back request)',name:d.name,mobile:String(d.mobile||'').slice(-10),city:d.city||'',state:d.state||'',branches:d.branches||'1',staff:d.staff||'—',interests:d.interests||'',stage:'New',at:new Date().toISOString(),notes:d.msg?[d.msg]:[]});audit('New website lead: '+(d.salon||d.name));save()});
PLATFORM.on('salonRequest',d=>{const t=T(d.tenant);S.reqs.unshift({id:'R-'+(2001+S.reqs.length),tenant:d.tenant,type:d.type,title:d.title,note:d.note,status:'Open',at:new Date().toISOString(),msgs:[]});audit(`New request from ${t?t.salon:d.tenant}: ${d.title}`);save()});
PLATFORM.on('vwhShareResult',d=>{S.vwh.forEach(w=>(w.shares||[]).forEach(s=>{if(s.id===d.ref){s.status=d.status;w.log.push({at:todayS+'T12:00:00',text:`Employee ${d.status} sharing with ${salonLabel(s.to)} in the staff app`});audit(`${w.name} ${d.status} sharing work history`)}}));save()});
PLATFORM.on('vwhWithdraw',d=>{const w=S.vwh.find(x=>x.mobile===d.mobile&&x.status==='Active');if(w)ACT.vwhWithdrawGo({dataset:{id:w.id}})});
PLATFORM.on('vwhOn',d=>{if(S.vwh.some(x=>x.mobile===d.mobile&&x.status==='Active'))return;const at=todayS+'T12:00:00';S.vwh.unshift({id:'W'+(7001+S.vwh.length),name:d.name,mobile:d.mobile,dob:d.dob||'',aadhaar4:d.a4||'----',pan:d.pan||'—',consentAt:at,confirmedAt:at,status:'Active',jobs:[{salon:'AURA01',role:d.role,from:d.doj,to:'',exit:'Present',verified:'Salon HR payroll records'}],checks:[],log:[{at,text:'Consent given in the staff app'}],shares:[]});audit('Verified work history opened for '+d.name);save()});

render();
}